html:
{%- import "costeo_yelke/templates/print/oc_yelke.html" as oc -%}
{#- Solicitud de material: lo que hay que comprar o traspasar para producir. Diseño: templates/print/oc_yelke.html -#}
{%- set tipos = {"Purchase": "Compra", "Material Transfer": "Traspaso", "Material Issue": "Salida de almacén",
    "Manufacture": "Producción", "Customer Provided": "Material del cliente"} -%}
{%- set almacenes = doc.items | map(attribute="warehouse") | select | unique | list -%}
{%- set fechas = doc.items | map(attribute="schedule_date") | select | unique | list -%}
{{ oc.estilos() }}
{{ oc.membrete_encabezado(doc, no_letterhead, print_settings, "Solicitud de material") }}
<div class="pdf-container">
{{ oc.marca_borrador(doc) }}
{{ oc.datos(doc, {"etiqueta": "Solicitó", "nombre": firmas_documento(doc)[0].nombre, "rfc": "", "direccion": []},
    [("Fecha de elaboración", fecha_corta(doc.transaction_date)),
     ("Requerida para", fecha_corta(doc.schedule_date)),
     ("Tipo", tipos.get(doc.material_request_type) or doc.material_request_type),
     ("Costeo", doc.get("costeo")),
     ("Almacén", almacenes[0] if almacenes | length == 1 else None)]) }}
<table class="items-table">
    <thead><tr>
        <th style="width:6mm">#</th><th>Artículo</th>
        {% if almacenes | length > 1 %}<th style="width:36mm">Almacén</th>{% endif %}
        {% if fechas | length > 1 %}<th style="width:24mm">Requerida</th>{% endif %}
        <th class="text-right" style="width:28mm">Cantidad</th>
    </tr></thead>
    <tbody>
    {% for row in doc.items %}
        <tr>
            <td class="muted">{{ row.idx }}</td>
            <td>{{ oc.celda_articulo(row) }}</td>
            {% if almacenes | length > 1 %}<td class="muted">{{ row.warehouse or "—" }}</td>{% endif %}
            {% if fechas | length > 1 %}<td class="muted">{{ fecha_corta(row.schedule_date) }}</td>{% endif %}
            <td class="num">{{ cantidad_uom(row.qty, row.uom or row.stock_uom) }}</td>
        </tr>
    {% endfor %}
    </tbody>
</table>
{{ oc.cierre(doc, mostrar_pagos=false, mostrar_totales=false) }}
</div>
{{ oc.membrete_pie(doc, no_letterhead, print_settings) }}
